create table if not exists public.timeline_daw_normalization_support_evidence_seals(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,head_hash text not null,link_count integer not null check(link_count>=0),seal_checksum text not null unique,previous_seal_id text references public.timeline_daw_normalization_support_evidence_seals(id),state text not null default 'active' check(state in('active','revoked','superseded')),revoked_at timestamptz,created_at timestamptz not null default now());alter table public.timeline_daw_normalization_support_evidence_seals enable row level security;create policy timeline_daw_normalization_support_evidence_seals_owner on public.timeline_daw_normalization_support_evidence_seals for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());create unique index if not exists timeline_daw_normalization_support_one_active_seal on public.timeline_daw_normalization_support_evidence_seals(owner_id,session_id) where state='active';create table if not exists public.timeline_daw_normalization_support_evidence_seal_events(id text primary key,seal_id text not null references public.timeline_daw_normalization_support_evidence_seals(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,event text not null check(event in('created','revoked','superseded')),reason text not null default '',created_at timestamptz not null default now());alter table public.timeline_daw_normalization_support_evidence_seal_events enable row level security;create policy timeline_daw_normalization_support_seal_events_owner on public.timeline_daw_normalization_support_evidence_seal_events for select to authenticated using(owner_id=auth.uid());create policy timeline_daw_normalization_support_seal_events_insert on public.timeline_daw_normalization_support_evidence_seal_events for insert to authenticated with check(owner_id=auth.uid());
